def solve_tsp(distance_matrix: list[list[int]]) -> int:
    n = len(distance_matrix)
    if n == 0:
      raise ValueError("Distance matrix is empty")
    for i in range(n):
      if any(d == float('inf') for d in distance_matrix[i]):
        raise ValueError("Distance matrix contains infinity values")

    def calculate_cost(route: list[int]) -> int:
      total_cost = 0
      for i in range(n - 1):
        total_cost += distance_matrix[route[i]][route[i + 1]]
      total_cost += distance_matrix[route[-1]][route[0]]  
      return total_cost

    best_cost = float('inf')
    for start_city in range(n):
      visited = [False] * n
      current_route = [start_city]
      visited[start_city] = True
      remaining_cities = n - 1
      while remaining_cities > 0:
        next_city = -1
        min_cost = float('inf')
        for city in range(n):
          if not visited[city] and distance_matrix[current_route[-1]][city] < min_cost:
            next_city = city
            min_cost = distance_matrix[current_route[-1]][city]
        current_route.append(next_city)
        visited[next_city] = True
        remaining_cities -= 1
      best_cost = min(best_cost, calculate_cost(current_route))

    return best_cost  
