def solve_shortest_path(distances: dict) -> int:
    graph = {
        'M': {'A': distances.get(('M', 'A'), float('inf')), 'B': distances.get(('M', 'B'), float('inf')), 'C': distances.get(('M', 'C'), float('inf')), 'D': distances.get(('M', 'D'), float('inf'))},
        'A': {'B': distances.get(('A', 'B'), float('inf')), 'C': distances.get(('A', 'C'), float('inf')), 'D': distances.get(('A', 'D'), float('inf'))},
        'B': {'C': distances.get(('B', 'C'), float('inf')), 'D': distances.get(('B', 'D'), float('inf'))},
        'C': {'D': distances.get(('C', 'D'), float('inf'))},
    }
    visited = set()
    current_node = 'M'
    shortest_distance = 0
    while len(visited) < 4:
        for neighbor in graph[current_node]:
            if neighbor not in visited and graph[current_node][neighbor] != float('inf'):
                visited.add(neighbor)
                shortest_distance += graph[current_node][neighbor]
                current_node = neighbor
                break
    return shortest_distance 
