def solve_shortest_path(distances: Dict[Tuple[str, str], int]) -> int:
    n = len(set(d[0] for d in distances) | set(d[1] for d in distances)) 
    dp = [[float('inf')] * (1 << n) for _ in range(n)]
    dp[0][1] = distances[('M', 'A')]

    for mask in range(1, 1 << n):
        for i in range(n):
            if (mask >> i) & 1:
                for j in range(n):
                    if (mask >> j) & 1 and i != j:
                        dp[i][mask] = min(dp[i][mask], dp[j][mask ^ (1 << i)] + distances[(str(j), str(i))])

    return min(dp[0][(1 << n) - 1]) 
