def count_grid_ways(numbers: list[int]) -> int:
    n = len(numbers)
    target_sum = sum(numbers) // 3
    dp = [[set() for _ in range(target_sum + 1)] for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = {frozenset()}

    for i in range(1, n + 1):
        for j in range(1, target_sum + 1):
            if j >= numbers[i - 1]:
                dp[i][j].update({frozenset(subset) | {numbers[i - 1]} for subset in dp[i - 1][j - numbers[i - 1]]})
            dp[i][j].update(dp[i - 1][j])

    return len(dp[n][target_sum])
