def maximize_profit_price(listed_price: float, current_customers: int, price_decrease: int, new_customers_per_decrease: int, cost_coefficients: list) -> float:
    n = current_customers
    cost = lambda n: cost_coefficients[0] * n**2 + cost_coefficients[1] * n + cost_coefficients[2]
    revenue = lambda p: (listed_price - p) * (current_customers + (listed_price - p) // price_decrease * new_customers_per_decrease)
    profit = lambda p: revenue(p) - cost(n + (listed_price - p) // price_decrease * new_customers_per_decrease)
    return round((lambda p: max(profit(p), profit(p + 1)))(), 2)

def maximize_profit_price(price: float, customers: int, price_decrease: int, new_customers: int, cost_coefficients: list) -> float:
    n = customers
    cost = lambda n: cost_coefficients[0] * n**2 + cost_coefficients[1] * n + cost_coefficients[2]
    revenue = lambda p: (price - price_decrease/1000) * (customers + new_customers * ((price - price_decrease/1000)/price_decrease))
    profit = lambda p: revenue(p) - cost(n)
    return round((price - price_decrease/1000), 2)

