def distance_point_to_line(p1: Tuple[float, float, float], p2: Tuple[float, float, float], p3: Tuple[float, float, float]) -> float:
    v1 = p2 - p1
    v2 = p3 - p1
    d = abs((v1[0] * v2[1] - v1[1] * v2[0])) / ((v1[0]**2 + v1[1]**2)**0.5)
    return d

def solve_gps_problem(a: Tuple[float, float, float], b: Tuple[float, float, float], c: Tuple[float, float, float], d: Tuple[float, float, float]) -> float:
    ab = (b[0] - a[0], b[1] - a[1], b[2] - a[2])
    m = (c[1] - a[1]) / (c[0] - a[0]) if c[0] != a[0] else float('inf')
    b_intercept = a[1] - m * a[0]
    t = ((c[1] - b_intercept) / (m - (b[1] - a[1]) / (b[0] - a[0]))) 
    if t < 0 or t > 1:
      return float('inf')
    M = (a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1]), a[2] + t * (b[2] - a[2]))
    return distance_point_to_line(M, a, c) + distance_point_to_line(M, b, c) + distance_point_to_line(M, d, c)

