def calculate_probability(total_tickets: int, num_tickets_drawn: int) -> float:
    """Calculates the probability of drawing at least two prime numbers and an even sum from a set of tickets.

    Args:
        total_tickets: The total number of tickets in the box.
        num_tickets_drawn: The number of tickets drawn simultaneously.

    Returns:
        The probability as a percentage rounded to one decimal place.
    """
    prime_count = 0
    for i in range(2, total_tickets + 1):
        is_prime = True
        for j in range(2, int(i**0.5) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            prime_count += 1

    total_combinations =  math.comb(total_tickets, num_tickets_drawn)
    favorable_combinations = 0

    for i in range(num_tickets_drawn):
        if i % 2 == 0:
            favorable_combinations += math.comb(prime_count, i // 2) * math.comb(total_tickets - prime_count, num_tickets_drawn - i // 2)

    return round((favorable_combinations / total_combinations) * 100, 1)
